NAME, KYC = range(2)

class KYCBot:
    def __init__(self, db_path: str, pepper: str, storage_path: str):
        self.db = UserDB(db_path)
        self.pepper = pepper
        self.storage_path = storage_path
        self.application = ApplicationBuilder().token(os.getenv("TELEGRAM_BOT_TOKEN")).build()
        
        # Set up conversation handler
        conv_handler = ConversationHandler(
            entry_points=[CommandHandler('start', self.start)],
            states={
                NAME: [MessageHandler(filters.TEXT & ~filters.COMMAND, self.set_name)],
                KYC: [MessageHandler(filters.Document.ALL, self.upload_kyc)]
            },
            fallbacks=[CommandHandler('start', self.start)]
        )
        
        # Add other handlers
        self.application.add_handler(CommandHandler('setname', self.set_name))
        self.application.add_handler(CommandHandler('uploadkyc', self.upload_kyc))
        self.application.add_handler(conv_handler)
        
    async def start(self, update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
        user = update.message.from_user
        telegram_id = user.id
        
        if not self.db.user_exists(telegram_id):
            # Request contact
            keyboard = ReplyKeyboardMarkup(
                [[KeyboardButton("Share my contact", request_contact=True)]],
                one_time_keyboard=True
            )
            await update.message.reply_text(
                "Please share your contact information to register.",
                reply_markup=keyboard
            )
            return NAME
        else:
            await update.message.reply_text("You are already registered. Use /setname or /uploadkyc")
            return ConversationHandler.END
    
    async def set_name(self, update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
        user = update.message.from_user
        telegram_id = user.id
        
        if update.message.contact:
            # Handle contact sharing
            phone = update.message.contact.phone_number
            if self.db.register_user(telegram_id, phone):
                await update.message.reply_text("Please provide your name:")
                return NAME
            else:
                await update.message.reply_text("You are already registered. Use /uploadkyc")
                return ConversationHandler.END
        else:
            name = update.message.text.strip()
            if not name or not name.replace(' ', '').isalpha():
                await update.message.reply_text("Please provide a valid name (letters and spaces only).")
                return NAME
                
            if self.db.update_name(telegram_id, name):
                await update.message.reply_text("Name updated successfully. Please upload your KYC document using /uploadkyc")
                return KYC
            else:
                await update.message.reply_text("Error updating name. Please try again.")
                return NAME
    
    async def upload_kyc(self, update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
        user = update.message.from_user
        telegram_id = user.id
        
        # Validate file
        file = update.message.document
        if file.file_size > 10 * 1024 * 1024:  # 10MB
            await update.message.reply_text("File too large. Maximum 10MB allowed.")
            return KYC
            
        if not file.mime_type.startswith(('image/', 'application/pdf')):
            await update.message.reply_text("Unsupported file type. Please upload PDF or image.")
            return KYC
            
        # Download file
        new_file = await context.bot.get_file(file.file_id)
        file_path = f"{self.storage_path}/{file.file_id}"
        await new_file.download_to_drive(file_path)
        
        # Get user's phone to derive key
        user_phone = self.db.get_user_phone(telegram_id)
        if not user_phone:
            await update.message.reply_text("User not registered. Please start with /start")
            return ConversationHandler.END
            
        # Encrypt file
        key = self._derive_key(user_phone)
        encrypted_path = f"{self.storage_path}/encrypted/{telegram_id}_{file.file_id}.enc"
        encrypt_file(file_path, encrypted_path, key)
        
        # Update DB
        if self.db.update_kyc(telegram_id, encrypted_path):
            await update.message.reply_text("KYC document uploaded successfully. Waiting for verification.")
        else:
            await update.message.reply_text("Error updating KYC. Please try again.")
            
        return ConversationHandler.END
    
    def _derive_key(self, phone: str) -> bytes:
        """Derive AES-256 key using PBKDF2 with phone and pepper"""
        salt = get_random_bytes(16)
        key = PBKDF2(self.pepper + phone, salt, 32, 100000, hmac_hash_module=hashlib.sha256)
        return key
    
    def run(self):
        self.application.run_polling()

